if(s.religions.length<desiredReligions&&livingRealms.length&&((s.religions.length===0&&s.year>=-2850)||((s.year+3000)%650===0&&s.year>-2850)||r.chance(.00035))){const eligibleHosts=livingRealms.filter(c=>c.provinces.length);if(eligibleHosts.length){const host=r.pick(eligibleHosts);const prophet=createPerson(s,host,r,'Religious Figure');prophet.stars=r.chance(.18)?5:4;foundReligion(s,host,prophet,r)}}
if(s.year>-1200&&s.wonders.length<18&&livingRealms.length&&((s.year+1200)%450===0||r.chance(.00035))){const hosts=livingRealms.filter(c=>c.technology>=100);if(hosts.length){const host=r.pick(hosts);let patron=s.people.filter(p=>p.active&&p.realmId===host.id&&p.stars===5).sort((a,b)=>b.impact-a.impact)[0];if(!patron){patron=createPerson(s,host,r,r.pick<PersonRole>(['Scientist','Engineer','Merchant','General','Artist','Religious Figure','Politician']));patron.stars=5}createWonder(s,host,patron,r)}}
